using AcxiomCRM.Data; using AcxiomCRM.Models; using AcxiomCRM.Services; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore; using System.Security.Claims;
namespace AcxiomCRM.Controllers;
[Authorize] public class CustomersController:Controller { private readonly ApplicationDbContext _db; private readonly IAuditService _audit; public CustomersController(ApplicationDbContext db,IAuditService audit){_db=db;_audit=audit;}
 public async Task<IActionResult> Index(string? q,string? status,int page=1){var query=_db.Customers.AsQueryable(); if(!User.IsInRole("Admin")&&!User.IsInRole("Manager")){var uid=User.FindFirstValue(ClaimTypes.NameIdentifier); query=query.Where(x=>x.OwnerId==uid);} if(!string.IsNullOrWhiteSpace(q)){var s=q.Trim(); query=query.Where(x=>x.CustomerName.Contains(s)||x.Email.Contains(s)||x.Phone.Contains(s)||(x.CompanyName!=null&&x.CompanyName.Contains(s)));} if(!string.IsNullOrWhiteSpace(status)) query=query.Where(x=>x.Status==status); ViewBag.Query=q;ViewBag.Status=status;ViewBag.Page=page;ViewBag.Pages=(int)Math.Ceiling(await query.CountAsync()/10.0);return View(await query.OrderByDescending(x=>x.Id).Skip((Math.Max(1,page)-1)*10).Take(10).ToListAsync());}
 public async Task<IActionResult> Details(int id){var item=await _db.Customers.FindAsync(id);if(item==null)return NotFound();return View(item);}
 
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> Create(Customer item){if(await _db.Customers.AnyAsync(x=>x.Email==item.Email||x.Phone==item.Phone))ModelState.AddModelError("","A customer with this email or phone already exists.");if(string.IsNullOrWhiteSpace(item.CustomerCode))item.CustomerCode="CUS-"+Guid.NewGuid().ToString("N")[..8].ToUpper();if(!ModelState.IsValid)return View(item);item.CreatedBy=User.FindFirstValue(ClaimTypes.NameIdentifier);if(item is Customer assigned && string.IsNullOrEmpty(assigned.OwnerId)){assigned.OwnerId=item.CreatedBy;}_db.Customers.Add(item);try{await _db.SaveChangesAsync();await _audit.WriteAsync("Create","Customer",item.Id.ToString(),newValue:System.Text.Json.JsonSerializer.Serialize(item));TempData["Success"]="Customer created successfully.";return RedirectToAction(nameof(Index));}catch(DbUpdateException){ModelState.AddModelError("","Could not save this record. Check for duplicate values and related records.");return View(item);}}
 public async Task<IActionResult> Edit(int id){var item=await _db.Customers.FindAsync(id);return item==null?NotFound():View(item);}
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> Edit(int id,Customer item){if(id!=item.Id)return BadRequest();if(await _db.Customers.AnyAsync(x=>x.Id!=id&&(x.Email==item.Email||x.Phone==item.Phone)))ModelState.AddModelError("","A customer with this email or phone already exists.");if(!ModelState.IsValid)return View(item);var old=await _db.Customers.AsNoTracking().FirstOrDefaultAsync(x=>x.Id==id);if(old==null)return NotFound();_db.Entry(item).State=EntityState.Modified;_db.Entry(item).Property(x=>x.CreatedDate).IsModified=false;_db.Entry(item).Property(x=>x.CreatedBy).IsModified=false;try{await _db.SaveChangesAsync();await _audit.WriteAsync("Update","Customer",id.ToString(),System.Text.Json.JsonSerializer.Serialize(old),System.Text.Json.JsonSerializer.Serialize(item));TempData["Success"]="Customer updated successfully.";return RedirectToAction(nameof(Index));}catch(DbUpdateException){ModelState.AddModelError("","Could not update this record. Check duplicate values and relationships.");return View(item);}}
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> Delete(int id){var item=await _db.Customers.FindAsync(id);if(item==null)return NotFound();var old=System.Text.Json.JsonSerializer.Serialize(item);item.Status="Inactive";try{await _db.SaveChangesAsync();await _audit.WriteAsync("Delete/Deactivate","Customer",id.ToString(),old);TempData["Success"]="Deactivate customer completed.";}catch(DbUpdateException){TempData["Error"]="This record is referenced by other records and cannot be deleted. Deactivate it instead.";}return RedirectToAction(nameof(Index));}

}
